	public static long knapsack(int[] weight, long[] value, int maxWeight){
		int n=value.length;
		long[] dp=new long[maxWeight+1];
		Arrays.fill(dp, 0);
		for(int i=0; i<n; i++){
			for(int j=maxWeight; j>=weight[i]; j--){
				dp[j]=Math.max(dp[j], value[i]+dp[j-weight[i]]);
			}
		}
		return dp[maxWeight];
	}

